mod bindings;

pub use bindings::*;
use std::ffi::CStr;
use std::fmt;

/// Get WolfSSL version via `LIBWOLFSSL_VERSION_STRING` header defined in wolfssl/version.h
pub fn get_wolfssl_version_string() -> &'static str {
    CStr::from_bytes_until_nul(LIBWOLFSSL_VERSION_STRING)
        .unwrap()
        .to_str()
        .unwrap()
}

/// Compile-time information generated by [`built`](https://docs.rs/built)
#[allow(dead_code)]
mod built_info {
    include!(concat!(env!("OUT_DIR"), "/built.rs"));
}

/// Describes how this `wolfssl-sys` was built, for diagnostics.
///
/// The [`Display`](fmt::Display) impl renders a single line suitable for
/// logging, e.g. `wolfssl-sys 5.1.0, wolfSSL 5.9.4, features: default,postquantum`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub struct BuildInfo {
    /// Version of the `wolfssl-sys` crate
    pub crate_version: &'static str,
    /// Version of the bundled wolfSSL C library
    pub wolfssl_version: &'static str,
    /// Enabled Cargo features of the `wolfssl-sys` crate
    pub features: &'static [&'static str],
}

impl fmt::Display for BuildInfo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "wolfssl-sys {}, wolfSSL {}, features: ",
            self.crate_version, self.wolfssl_version
        )?;
        if self.features.is_empty() {
            f.write_str("none")
        } else {
            f.write_str(&self.features.join(","))
        }
    }
}

/// Get build information for this `wolfssl-sys` crate
pub fn build_info() -> BuildInfo {
    BuildInfo {
        crate_version: built_info::PKG_VERSION,
        wolfssl_version: get_wolfssl_version_string(),
        features: &built_info::FEATURES_LOWERCASE,
    }
}

/**
 * Add more tests to gain more confidence in the bindings
 */
#[cfg(test)]
mod tests {
    use std::os::raw::c_int;

    use test_case::test_case;
    #[cfg(unix)]
    type CurveGroupType = std::os::raw::c_uint;
    #[cfg(windows)]
    type CurveGroupType = std::os::raw::c_int;

    use super::*;
    #[test]
    fn init_wolfssl() {
        unsafe {
            let res = wolfSSL_Init();
            assert_eq!(res, WOLFSSL_SUCCESS as c_int);
        }
    }

    #[test]
    fn build_info_crate_version_matches_cargo_toml() {
        let manifest = include_str!("../Cargo.toml");
        let expected = format!("version = \"{}\"", build_info().crate_version);
        assert!(manifest.lines().any(|l| l.trim() == expected));
    }

    #[test]
    fn build_info_features_match_cfg() {
        let features = build_info().features;
        assert_eq!(
            features.contains(&"postquantum"),
            cfg!(feature = "postquantum")
        );
        assert_eq!(features.contains(&"debug"), cfg!(feature = "debug"));
    }

    #[test]
    fn build_info_display() {
        let info = BuildInfo {
            crate_version: "1.2.3",
            wolfssl_version: "4.5.6",
            features: &["debug", "postquantum"],
        };
        assert_eq!(
            info.to_string(),
            "wolfssl-sys 1.2.3, wolfSSL 4.5.6, features: debug,postquantum"
        );

        let info = BuildInfo {
            features: &[],
            ..info
        };
        assert_eq!(
            info.to_string(),
            "wolfssl-sys 1.2.3, wolfSSL 4.5.6, features: none"
        );
    }

    #[cfg(feature = "postquantum")]
    #[test_case(WOLFSSL_SECP521R1MLKEM1024)]
    fn test_post_quantum_available(group: CurveGroupType) {
        unsafe {
            // Init WolfSSL
            let res = wolfSSL_Init();
            assert_eq!(res, WOLFSSL_SUCCESS as c_int);

            // Set up client method
            let method = wolfTLSv1_3_client_method();

            // Create context
            let context = wolfSSL_CTX_new(method);

            // Create new SSL stream
            let ssl = wolfSSL_new(context);

            let res = wolfSSL_UseKeyShare(ssl, group.try_into().unwrap());

            // Check that ML-KEM was enabled
            assert_eq!(res, WOLFSSL_SUCCESS as c_int);
        }
    }

    #[test]
    fn test_wolfssl_version_is_not_empty() {
        assert!(!get_wolfssl_version_string().is_empty())
    }
}
